import{useEffect}from"react";export default function useFadeInOnView(selector=".fade-up"){useEffect((()=>{const elements=document.querySelectorAll(selector),observer=new IntersectionObserver((entries=>{entries.forEach((entry=>{entry.isIntersecting?entry.target.classList.add("show"):entry.target.classList.remove("show")}))}),{threshold:.2});return elements.forEach((el=>observer.observe(el))),()=>observer.disconnect()}),[selector])}